    if (|{u_i.u_core.oh[0][2], u_i.u_core.oh[1][2], u_i.u_core.oh[2][2], u_i.u_core.oh[3][2], u_i.u_core.oh[4][2], u_i.u_core.oh[5][2], u_i.u_core.oh[6][2], u_i.u_core.oh[7][2], u_i.u_core.oh[8][2], u_i.u_core.oh[9][2], u_i.u_core.oh[10][2], u_i.u_core.oh[11][2], u_i.u_core.oh[12][2], u_i.u_core.oh[13][2], u_i.u_core.oh[14][2], u_i.u_core.oh[15][2], u_i.u_core.oh[16][2], u_i.u_core.oh[17][2], u_i.u_core.oh[18][2], u_i.u_core.oh[19][2], u_i.u_core.oh[20][2], u_i.u_core.oh[21][2], u_i.u_core.oh[22][2], u_i.u_core.oh[23][2], u_i.u_core.oh[24][2], u_i.u_core.oh[25][2], u_i.u_core.oh[26][2], u_i.u_core.oh[27][2], u_i.u_core.oh[28][2], u_i.u_core.oh[29][2], u_i.u_core.oh[30][2], u_i.u_core.oh[31][2], u_i.u_core.oh[32][2], u_i.u_core.oh[33][2]}) i_lane_sel[2]++;
    if (|{u_i.u_core.oh[0][3], u_i.u_core.oh[1][3], u_i.u_core.oh[2][3], u_i.u_core.oh[3][3], u_i.u_core.oh[4][3], u_i.u_core.oh[5][3], u_i.u_core.oh[6][3], u_i.u_core.oh[7][3], u_i.u_core.oh[8][3], u_i.u_core.oh[9][3], u_i.u_core.oh[10][3], u_i.u_core.oh[11][3], u_i.u_core.oh[12][3], u_i.u_core.oh[13][3], u_i.u_core.oh[14][3], u_i.u_core.oh[15][3], u_i.u_core.oh[16][3], u_i.u_core.oh[17][3], u_i.u_core.oh[18][3], u_i.u_core.oh[19][3], u_i.u_core.oh[20][3], u_i.u_core.oh[21][3], u_i.u_core.oh[22][3], u_i.u_core.oh[23][3], u_i.u_core.oh[24][3], u_i.u_core.oh[25][3], u_i.u_core.oh[26][3], u_i.u_core.oh[27][3], u_i.u_core.oh[28][3], u_i.u_core.oh[29][3], u_i.u_core.oh[30][3], u_i.u_core.oh[31][3], u_i.u_core.oh[32][3], u_i.u_core.oh[33][3]}) i_lane_sel[3]++;
    if (|{u_i.u_core.oh[0][4], u_i.u_core.oh[1][4], u_i.u_core.oh[2][4], u_i.u_core.oh[3][4], u_i.u_core.oh[4][4], u_i.u_core.oh[5][4], u_i.u_core.oh[6][4], u_i.u_core.oh[7][4], u_i.u_core.oh[8][4], u_i.u_core.oh[9][4], u_i.u_core.oh[10][4], u_i.u_core.oh[11][4], u_i.u_core.oh[12][4], u_i.u_core.oh[13][4], u_i.u_core.oh[14][4], u_i.u_core.oh[15][4], u_i.u_core.oh[16][4], u_i.u_core.oh[17][4], u_i.u_core.oh[18][4], u_i.u_core.oh[19][4], u_i.u_core.oh[20][4], u_i.u_core.oh[21][4], u_i.u_core.oh[22][4], u_i.u_core.oh[23][4], u_i.u_core.oh[24][4], u_i.u_core.oh[25][4], u_i.u_core.oh[26][4], u_i.u_core.oh[27][4], u_i.u_core.oh[28][4], u_i.u_core.oh[29][4], u_i.u_core.oh[30][4], u_i.u_core.oh[31][4], u_i.u_core.oh[32][4], u_i.u_core.oh[33][4]}) i_lane_sel[4]++;
